#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_safeMode;
uniform float amzp_cellSize;
uniform float amzp_neighborRange;
uniform float amzp_gradPull;
uniform float amzp_jitter;
uniform float amzp_seed;
uniform float amzp_alpha;







    const int MaxNeighbor = 2;  
    const int MaxPoints   = 12; 


    float hash21(float2 p){ return fract(sin(dot(p, float2(127.1,311.7)) + amzp_seed*53.0) * 43758.5453); }
    float2 hash22(float2 p){ return float2(hash21(p), hash21(p*1.37+19.7)); }


    float4 fetchColorPx(float2 posPx){
      float2 uv = clamp(posPx / max(screen.zw, float2(1.0)), 0.0, 1.0);
      return amzTexture(0, uv);
    }


    float computeValue(float2 posPx){
      float4 c = fetchColorPx(posPx);

      float lum = dot(c.rgb, float3(0.2126, 0.7152, 0.0722));
      float e = dot(c, float4(-1.0, 2.0, -1.0, 0.0));
      float m = clamp(0.5 + 0.5 * e, 0.0, 1.0);
      return mix(lum, lum * (0.8 + 0.4*m), 0.6);
    }


    float2 computeGradientPx(float2 posPx, float eps){
      float he = max(eps*0.5, 0.5);
      float2 dx = float2(he, 0.0);
      float2 dy = float2(0.0, he);
      float gx = computeValue(posPx + dx) - computeValue(posPx - dx);
      float gy = computeValue(posPx + dy) - computeValue(posPx - dy);
      return float2(gx, gy) / max(eps, 1.0);
    }


    float2 generatePoint(int2 cell, float tileSize){
      float2 cellF = float2(cell);
      float2 rnd = hash22(cellF);

      float2 base = cellF + float2(1.0, 0.0) * (mod(float(cell.y), 2.0) - 0.5) * 0.5
                        + (rnd - 0.5) * amzp_jitter;
      float2 p = base * tileSize;

      if(amzp_gradPull > 0.0){
        float2 g = computeGradientPx(p, tileSize);
        float amzSource_gl = length(g);
        float2 ng = (amzSource_gl < 1e-4) ? (rnd - 0.5) * 0.1 : normalize(g);
        float lenPx = min(0.005 / max(amzSource_gl, 1e-4), 1.0) * tileSize * amzp_gradPull;
        p -= ng * lenPx;
      }
      return p;
    }


    bool pointInTri(float2 p, float2 a, float2 b, float2 c){
      float2 v0=b-a, v1=c-a, v2=p-a;
      float d00=dot(v0,v0), d01=dot(v0,v1), d02=dot(v0,v2);
      float d11=dot(v1,v1), d12=dot(v1,v2);
      float inv=1.0/max(d00*d11 - d01*d01, 1e-6);
      float u=(d11*d02 - d01*d12)*inv;
      float v=(d00*d12 - d01*d02)*inv;
      return (u>=0.0)&&(v>=0.0)&&((u+v)<1.0);
    }

    float2 isectLines(float2 p1, float2 d1, float2 p2, float2 d2){
      float det = d1.x*d2.y - d1.y*d2.x;
      float2 df = p2 - p1;
      float t = (df.x*d2.y - df.y*d2.x) / max(abs(det), 1e-6);
      return p1 + d1 * t;
    }

    float2 gPts[MaxPoints];
    float gDist[MaxPoints];
    bool circumEmpty(int i1,int i2,int i3){
      float2 c = isectLines((gPts[i1]+gPts[i2])*0.5, (gPts[i2]-gPts[i1]).yx*float2(1.0,-1.0),
                          (gPts[i1]+gPts[i3])*0.5, (gPts[i3]-gPts[i1]).yx*float2(1.0,-1.0));
      float r = length(gPts[i1]-c);
      for(int i=0;i<MaxPoints;i++){
        if(i==i1||i==i2||i==i3) continue;
        if(length(gPts[i]-c) < r) return false;
      }
      return true;
    }

    void amzRender(){

      float2 fragPx = amzScreenNorm() * screen.zw; 
      float tileSize = max(amzp_cellSize, 1.0);
      float2 gpos = floor(fragPx / tileSize + 0.5);

      float2 labCentroid;
      if((amzp_safeMode>0.5)){

        int2 c0 = int2(int(gpos.x), int(gpos.y));
        float2 pt0 = generatePoint(c0, tileSize);
        float2 pt1 = generatePoint(c0 + int2(1,0), tileSize);
        float2 pt2 = generatePoint(c0 + int2(0,1), tileSize);
        labCentroid = (pt0 + pt1 + pt2) / 3.0;
      } else {

        for(int i=0;i<MaxPoints;i++){ gDist[i]=1e9; gPts[i]=float2(0.0); }
        int r = int(clamp(float(amzp_neighborRange), 1.0, float(MaxNeighbor)));
        for(int dy=-MaxNeighbor; dy<=MaxNeighbor; dy++){
          for(int dx=-MaxNeighbor; dx<=MaxNeighbor; dx++){
            if(amzIntAbs(dx)>r || amzIntAbs(dy)>r) continue;
            int2 cell = int2(int(gpos.x) + dx, int(gpos.y) + dy);
            float2 pt = generatePoint(cell, tileSize);
            float d = length(fragPx - pt);

            for(int k=0;k<MaxPoints;k++){
              if(d < gDist[k]){
                float td=gDist[k]; gDist[k]=d; d=td;
                float2 tp=gPts[k]; gPts[k]=pt; pt=tp;
              }
            }
          }
        }

        bool found=false; int i1=0,i2=1,i3=2; int N=8;
        for(int a=0; a<MaxPoints; a++){
          if(a>=N) break;
          for(int b=0; b<MaxPoints; b++){
            if(b>=N) break;
            if(b==a) continue;
            for(int c=0; c<MaxPoints; c++){
              if(c>=N) break;
              if(c==a || c==b) continue;
              if(pointInTri(fragPx, gPts[a], gPts[b], gPts[c]) && circumEmpty(a,b,c)){
                i1=a; i2=b; i3=c; found=true; break;
              }
            }
            if(found) break;
          }
          if(found) break;
        }
        if(found){
          labCentroid = (gPts[i1] + gPts[i2] + gPts[i3]) / 3.0;
        } else {

          labCentroid = (gPts[0] + gPts[1] + gPts[2]) / 3.0;
        }
      }
      float4 col = fetchColorPx(labCentroid);


      float aSrc = amzTexture(0, amzScreenNorm()).a;
      amzOutput = float4(col.rgb, 1.0) * aSrc * amzp_alpha;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

